/* Scroll Escape — dependency-free hackathon MVP. Educational support, not medical treatment. */
const KEY='scroll-escape-progress-v1';
const initial={xp:0,completed:[],missions:0,reflections:[],beliefs:[],sosCount:0,sosHistory:[],gameHistory:[],unhookHistory:[]};
let state;try{state={...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state={...initial}};
let escapeChoice='move',escapeStep=0;
let unhook={step:'entry',trigger:'bored',want:'rest',intent:'',plan:'',pauseStarted:0,pausedFor:0,feedCount:0,choice:null,recordId:null,recommendation:null,recommendationBusy:false,recommendationError:''};
let pauseInterval=null;
const feedPosts=[
 {icon:'🥔',title:'POTATO BREAKS WORLD RECORD',desc:'Local potato reportedly learned three dance moves.'},
 {icon:'🐸',title:'FROG STARTS A PODCAST',desc:'Episode 1: Opinions on puddles. Episode 2: More puddles.'},
 {icon:'🦆',title:'DUCK DECLARES ITSELF CEO',desc:'Company stock now paid entirely in breadcrumbs.'}
];
function unhookLog(choice){const record={id:crypto.randomUUID?.()||String(Date.now()),at:new Date().toISOString(),trigger:unhook.trigger,desiredReward:unhook.want,intention:unhook.plan||null,choice,feedPostsViewed:unhook.feedCount,pauseSeconds:unhook.pausedFor,recommendation:unhook.recommendation?{game:unhook.recommendation.game,lesson:unhook.recommendation.lesson,source:unhook.recommendation.source}:null,reflection:null};state.unhookHistory.push(record);state.unhookHistory=state.unhookHistory.slice(-150);unhook.recordId=record.id;save()}
function unhookStart(){unhook={step:'gate',trigger:'bored',want:'rest',intent:'',plan:'',pauseStarted:0,pausedFor:0,feedCount:0,choice:null,recordId:null,recommendation:null,recommendationBusy:false,recommendationError:''};view='unhook';render()}
function unhookPause(){unhook.step='pause';unhook.pauseStarted=Date.now();unhook.pausedFor=0;render();startPauseClock()}
function stopPauseClock(){if(pauseInterval){clearInterval(pauseInterval);pauseInterval=null}}
function startPauseClock(){stopPauseClock();pauseInterval=setInterval(()=>{if(view!=='unhook'||unhook.step!=='pause'){stopPauseClock();return}unhook.pausedFor=Math.min(30,Math.floor((Date.now()-unhook.pauseStarted)/1000));const node=$('#unhook-seconds');if(node)node.textContent=String(unhook.pausedFor);const fill=$('#unhook-pause-fill');if(fill)fill.style.width=(unhook.pausedFor/30*100)+'%';if(unhook.pausedFor>=30)stopPauseClock()},200)}
function unhookChoose(choice){stopPauseClock();unhook.choice=choice;unhookLog(choice);unhook.step=choice==='leave'?'leave':'feed';render()}
function unhookFeedback(answer){const rec=state.unhookHistory.find(x=>x.id===unhook.recordId);if(rec){rec.reflection=answer;rec.reflectedAt=new Date().toISOString();save()}unhook.step='reflected';render()}
// Keep routing deterministic and limited to existing, playable games and lessons.
const unhookRoutes={
 bored:{game:'loop',lesson:'loop',insight:'A quick distraction and a satisfying break are not always the same.',action:'Choose one small enjoyable activity away from the feed.'},
 stressed:{game:'adventure',lesson:'stress',insight:'You may be looking for relief. A short experiment can help you learn what restores you.',action:'Try a short break without the feed and check how you feel.'},
 stuck:{game:'switch',lesson:'switch',insight:'The next task may feel too big. Starting with one tiny step can lower the barrier.',action:'Open what you meant to work on and take one 30-second step.'},
 fomo:{game:'notifications',lesson:'fomo',insight:'Not every alert needs an answer immediately.',action:'Silence one optional notification while you do your next activity.'}
};
const unhookGameLessons={loop:'loop',switch:'switch',notifications:'fomo',adventure:'stress'};
function getUnhookRecommendation(){
 if(!unhook.recommendation){unhook.recommendation={...unhookRoutes[unhook.trigger],source:'local'};}
 return unhook.recommendation;
}
async function personalizeUnhook(){
 if(unhook.recommendationBusy)return;
 unhook.recommendationBusy=true;unhook.recommendationError='';render();
 const requestedTrigger=unhook.trigger,requestedWant=unhook.want;
 try{
  const rewardNames={rest:'a real break',fun:'something fun',escape:'space from stress',connection:'connection'};
  const response=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selectedTrigger:requestedTrigger,message:`I am feeling ${requestedTrigger}. I want ${rewardNames[requestedWant]}.`})});
  if(!response.ok)throw new Error('AI unavailable');
  const data=await response.json();
  if(!['loop','switch','notifications','adventure'].includes(data.game))throw new Error('Invalid recommendation');
  if(view==='unhook'&&unhook.step==='recommend'&&unhook.trigger===requestedTrigger&&unhook.want===requestedWant){
   unhook.recommendation={game:data.game,lesson:unhookGameLessons[data.game],insight:String(data.insight||'').slice(0,260),action:String(data.action||'').slice(0,240),source:data.source==='ai'?'ai':'local'};
  }
 }catch{unhook.recommendationError='AI is unavailable. Your local suggestion is ready.';}
 finally{unhook.recommendationBusy=false;if(view==='unhook'&&unhook.step==='recommend')render();}
}
function launchUnhookGame(){const r=getUnhookRecommendation();return startPractice(r.game==='adventure'?'reward':r.game)}
function launchUnhookLesson(){const r=getUnhookRecommendation();lessonId=r.lesson;option='';view='learn';render();window.scrollTo(0,0)}
function unhookView(){const steps={gate:1,reward:2,pause:3,recommend:4,decision:5,feed:6,leave:6,reflection:7,reflected:7};const label=`<div class="eyebrow">UNHOOK MOMENT · ${steps[unhook.step]||1}/7</div>`;let inner='';
 if(unhook.step==='gate')inner=`${label}<h1>What brought you here?</h1><p class="unhook-lead">Pick the closest feeling. There is no wrong answer.</p><div class="unhook-choice-grid v16-single-choice">${[['bored','😶','Bored'],['stressed','🌧️','Stressed'],['stuck','🪜','Avoiding a task'],['fomo','🔔','Just checking']].map(x=>`<button class="unhook-option" data-unhook-trigger="${x[0]}"><span>${x[1]}</span>${x[2]} <span class="v16-arrow">→</span></button>`).join('')}</div>`;
 if(unhook.step==='reward')inner=`${label}<h1>What are you hoping for?</h1><p class="unhook-lead">One thing you want scrolling to give you right now.</p><div class="unhook-choice-grid v16-single-choice">${[['rest','🌿','A real break'],['fun','✨','Something fun'],['escape','☁️','Escape for a bit'],['connection','♡','Connection']].map(x=>`<button class="unhook-option" data-unhook-want="${x[0]}"><span>${x[1]}</span>${x[2]} <span class="v16-arrow">→</span></button>`).join('')}</div>`;
 if(unhook.step==='pause')inner=`${label}<h1>Notice the wave 🌊</h1><p class="unhook-lead">You can notice the urge without fighting it. A pause is optional — not a test.</p><div class="unhook-wave" aria-hidden="true"><span class="wave-character">${nibArt('curious')}</span><span class="unhook-wave-line"></span></div><div class="unhook-count"><strong id="unhook-seconds">${unhook.pausedFor}</strong><span>/ 30 seconds · optional</span></div><div class="unhook-track"><div id="unhook-pause-fill" style="width:${unhook.pausedFor/30*100}%"></div></div><p class="small-note">Notice your feet or take a comfortable breath. Urges can vary; there's no required feeling.</p><div class="actions">${button('I’m ready to choose →','unhookDecision','btn-primary btn-wide')}</div>`;
 if(unhook.step==='recommend'){
 const r=getUnhookRecommendation(), lesson=getLesson(r.lesson);
 inner=`${label}<h1>Here's your next skill</h1><p class="unhook-lead">Based on what you shared, here's a short practice and a matching lesson. Both are optional.</p><div class="unhook-quest"><div class="eyebrow">${r.source==='ai'?'AI RECOMMENDATION':'PRIVATE ON-DEVICE SUGGESTION'}</div><h2>🎮 ${escapeHTML(gameLabels[r.game]||'Escape the Loop')}</h2><p>${escapeHTML(r.insight)}</p><p><strong>📚 ${escapeHTML(lesson.title)}</strong> · ${escapeHTML(lesson.subtitle)}</p><p class="small-note">A tiny next step: ${escapeHTML(r.action)}</p></div><div class="actions">${button('Try the recommended game →','unhookPlay','btn-primary btn-wide')}</div><div class="unhook-links"><button class="small-link" data-action="unhookLearn">Read the short lesson</button><button class="small-link" data-action="unhookDecision">Skip — make my choice</button></div><p class="small-note">${r.source==='ai'?'AI used only the two answers above. No journal history was sent.':'Everything above was selected locally. Your answers stay on this device unless you request AI.'}</p>${button(unhook.recommendationBusy?'Personalizing…':'Personalize using AI ✦','unhookAI','btn-dark btn-wide')}${unhook.recommendationError?`<p class="small-note" role="status">${escapeHTML(unhook.recommendationError)}</p>`:''}`;
 }
 if(unhook.step==='decision')inner=`${label}<h1>What would you like to do?</h1><p class="unhook-lead">You were hoping for <strong>${escapeHTML(({rest:'a break',fun:'something fun',escape:'some space',connection:'connection'})[unhook.want])}</strong>. What choice fits your goal right now?</p><label class="unhook-label" for="unhook-plan">Optional: My stopping cue / next tiny action</label><input id="unhook-plan" maxlength="120" placeholder="e.g. I'll watch 3 posts, then close" value="${escapeHTML(unhook.plan)}"><div class="actions">${button('Leave the feed and do something else ↗','unhookLeave','btn-primary btn-wide')}${button('Continue intentionally to demo feed','unhookContinue','btn-dark btn-wide')}</div><p class="small-note">Both choices are allowed. There is no punishment or lost streak.</p>`;
 if(unhook.step==='feed'){const post=feedPosts[Math.min(unhook.feedCount,2)];inner=`<div class="eyebrow">REELWORLD · FICTIONAL FEED · ${unhook.feedCount+1}/3</div><h1>ReelWorld <span class="unhook-pill">DEMO ONLY</span></h1><div class="reel-post"><div class="reel-art">${post.icon}</div><h2>${post.title}</h2><p>${post.desc}</p></div><p class="small-note">This is a finite, fictional feed. It is not Instagram or TikTok.</p><div class="actions">${button('Close feed ↗','unhookFeedExit','btn-primary btn-wide')}${unhook.feedCount<2?button('Next silly post →','unhookFeedNext','btn-dark btn-wide'):button('How did that feel? →','unhookReflect','btn-dark btn-wide')}</div>`}
 if(unhook.step==='leave')inner=`${label}<h1>You made a choice. 🌱</h1><p class="unhook-lead">You don't need to earn permission to leave your phone.</p><div class="unhook-quest"><h2>Your tiny next step</h2><p>${escapeHTML(unhook.plan||({'bored':'Stand up and find one interesting thing in the room.','stressed':'Take a comfortable breath and move to a different spot.','stuck':'Open the thing you meant to start. Just open it.','fomo':'Put your phone down and return to what matters to you.'}[unhook.trigger]))}</p></div><div class="actions">${button('I’ll put my phone down now','unhookHome','btn-primary btn-wide')}${button('Reflect later / now','unhookReflect','btn-dark btn-wide')}</div><p class="small-note">When you return, you can reflect in Journey. No reminder or countdown required.</p>`;
 if(unhook.step==='reflection')inner=`${label}<h1>What did you notice?</h1><p class="unhook-lead">Did your choice meet the need you came here with?</p><div class="unhook-choice-grid">${[['better','Better than expected'],['same','About as expected'],['worse','Less satisfying than expected'],['unsure','Not sure yet']].map(x=>`<button class="unhook-option" data-unhook-feedback="${x[0]}">${x[1]}</button>`).join('')}</div><div class="actions">${button('Skip reflection','unhookHome','btn-dark btn-wide')}</div>`;
 if(unhook.step==='reflected')inner=`${label}<h1>Insight saved ✦</h1><p class="unhook-lead">Your experience matters more than a perfect score. Come back to it in Journey whenever you're ready.</p><div class="actions">${button('Leave the app →','unhookHome','btn-primary btn-wide')}</div>`;
 return `<section class="unhook-page"><div class="unhook-header"><span class="unhook-tag">A SMALL SPACE TO CHOOSE</span><button class="unhook-close" data-action="unhookHome" aria-label="Close Unhook Moment">×</button></div><div class="unhook-card">${inner}</div><p class="unhook-disclaimer">Self-management prototype · not a medical treatment · this cannot interrupt real social media apps.</p></section>`;
}

let aiSuggestion=null, aiBusy=false, aiError='', sosDescription='';
let view='home',game=null,phase=0,context='bored',option='',targetCount=0,gameTimer=null,remaining=15,stepIndex=0,missionAnswered=false,lessonId=null,sessionComplete=false;
const lessons=[
{id:'loop',icon:'🔁',title:'The endless loop',subtitle:'Why “just one more” is so tempting',insight:'Short-form feeds remove natural stopping points. Choosing a stopping cue beforehand can make intentional use easier.',quest:'Before your next scroll, decide what will tell you it is time to finish.',belief:'I need one more video to feel satisfied'},
{id:'stress',icon:'🧠',title:'Rest or escape?',subtitle:'Stress relief is not always restoration',insight:'Scrolling may distract you from stress, but distraction and genuine rest are not always the same. Your own experience can help you tell the difference.',quest:'Try a two-minute phone-free break. Notice whether you feel more rested afterward.',belief:'Scrolling is the only way I can relax'},
{id:'switch',icon:'🪜',title:'Make the next step tiny',subtitle:'A bridge from scrolling to action',insight:'Stopping one activity and starting another are different skills. Shrinking the next task can reduce the friction of switching.',quest:'Open the thing you want to do next and complete only its first tiny step.',belief:'I must feel motivated before starting'},
{id:'fomo',icon:'🔔',title:'Notification noise',subtitle:'Not every alert needs you',insight:'Notifications can interrupt your plans even when they are not urgent. You can choose when and how to check them.',quest:'Mute one nonessential notification category for the rest of today.',belief:'I have to check right away'},
{id:'urge',icon:'🌊',title:'An urge is not an order',subtitle:'Learn to notice without obeying',insight:'An urge can be uncomfortable without requiring immediate action. You can notice it, choose a response, and check how it changes.',quest:'When an urge appears, name it and notice it for 20 seconds before choosing what to do.',belief:'If I feel the urge, I must act on it'}
];
const scenarios={bored:{label:'I’m bored',icon:'🎈',lesson:'loop',prompt:'Your brain is asking for stimulation. What other quick activity could be interesting?'},stressed:{label:'I’m stressed',icon:'🌧️',lesson:'stress',prompt:'You may be looking for relief. Let’s distinguish a break from a reset.'},stuck:{label:'I can’t stop',icon:'🌀',lesson:'switch',prompt:'Switching tasks can be difficult. We can make the next step very small.'},fomo:{label:'I might miss out',icon:'🔔',lesson:'fomo',prompt:'An alert can feel urgent even when it can wait.'}};
// Save synchronously for legacy/offline compatibility, and mirror into IndexedDB.
let dbHandle=null, saveQueue=Promise.resolve();
function openProgressDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(new Error('IndexedDB unavailable'));const req=indexedDB.open('escape-the-loop',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('records'))db.createObjectStore('records')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbWrite(db,key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function dbRead(db,key){return new Promise((resolve,reject)=>{const tx=db.transaction('records','readonly');const req=tx.objectStore('records').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function cleanState(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Invalid progress file');const safe={...initial,...input};safe.xp=Math.max(0,Math.min(10000000,Number(safe.xp)||0));safe.missions=Math.max(0,Math.min(1000000,Number(safe.missions)||0));safe.sosCount=Math.max(0,Math.min(1000000,Number(safe.sosCount)||0));for(const key of ['completed','reflections','beliefs','sosHistory','gameHistory','unhookHistory'])if(!Array.isArray(safe[key]))safe[key]=[];safe.completed=safe.completed.filter(x=>typeof x==='string').slice(0,50);for(const key of ['reflections','beliefs','sosHistory','gameHistory','unhookHistory'])safe[key]=safe[key].filter(x=>x&&typeof x==='object'&&!Array.isArray(x)).slice(-250);return safe}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('Local backup unavailable',e)}if(dbHandle){const snapshot=structuredClone(state);saveQueue=saveQueue.catch(()=>{}).then(()=>dbWrite(dbHandle,'progress',snapshot)).catch(e=>console.warn('IndexedDB write failed',e))}}
async function initStorage(){try{dbHandle=await openProgressDB();const saved=await dbRead(dbHandle,'progress');if(saved){state=cleanState(saved)}else{state=cleanState(state);save()}}catch(e){console.warn('Using localStorage fallback',e);state=cleanState(state)}render()}
function recordSOS(){if(!aiSuggestion)return;const entry={id:crypto.randomUUID?.()||String(Date.now()),at:new Date().toISOString(),trigger:context,game:aiSuggestion.game,action:aiSuggestion.action,source:aiSuggestion.source,helpfulness:null,attempted:null};state.sosHistory.push(entry);state.sosHistory=state.sosHistory.slice(-100);save()}
function logGame(id,tried){state.gameHistory.push({game:id,at:new Date().toISOString(),actionAttempted:!!tried});state.gameHistory=state.gameHistory.slice(-150);save()}
function backupProgress(){const payload={app:'escape-the-loop',version:1,exportedAt:new Date().toISOString(),progress:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='escape-the-loop-backup.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup downloaded. Keep it private.')}
async function importProgress(file){if(!file)return;try{if(file.size>1024*1024)throw new Error('Backup too large');const data=JSON.parse(await file.text());if(data.app!=='escape-the-loop'||data.version!==1)throw new Error('Not an Escape the Loop backup');const restored=cleanState(data.progress);if(!confirm('Replace current progress with the imported backup?'))return;state=restored;save();await saveQueue;render();toast('Progress restored from backup')}catch(e){alert('Could not import backup: '+e.message)}}
function feedbackSOS(id,helpfulness,attempted){const item=state.sosHistory.find(x=>x.id===id);if(!item)return;item.helpfulness=helpfulness;item.attempted=attempted;item.reviewedAt=new Date().toISOString();save();render();toast('Reflection saved on this device')}

function $(s){return document.querySelector(s)}
function escapeHTML(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function getLesson(id){return lessons.find(x=>x.id===id)||lessons[0]}
function button(label,fn,cls='btn-primary',extra=''){return `<button class="btn ${cls} ${extra}" data-action="${fn}" ${extra.includes('disabled')?'disabled':''}>${label}</button>`}
function header(){return `<header class="topbar"><div class="brand"><span class="brand-mark" aria-hidden="true">◌</span> scroll escape</div><div class="topright"><span class="quiet-level">Level ${Math.floor(state.xp/150)+1}</span></div></header>`}
function nav(){return `<nav class="nav" aria-label="Main navigation"><div class="nav-inner">${[['home','⌂','Home'],['games','◇','Play'],['learn','▤','Learn'],['progress','◷','Journey']].map(x=>`<button data-view="${x[0]}" class="${view===x[0]?'active':''}" aria-label="${x[2]}"><b aria-hidden="true">${x[1]}</b>${x[2]}</button>`).join('')}</div></nav>`}
function dashboard(){return `<section class="v16-home"><div class="v16-home-content"><div class="eyebrow">ESCAPE THE LOOP</div><div class="v16-nib" aria-hidden="true">${nibArt('curious')}</div><h1>One moment.<br><em>One choice.</em></h1><p>Feeling pulled into scrolling? Take a short pause and choose what happens next.</p>${button('Start Unhook →','startUnhook','btn-primary btn-wide')}<div class="v16-reassurance">No pressure · About a minute · Always your choice</div></div></section>`}
function escapeView(){const choices={move:{icon:'🚶',label:'Move my body',action:'Stand up. Walk to a doorway, stretch your arms, or step outside for one minute.',why:'Movement gives you a change of scene.'},make:{icon:'✏️',label:'Make something',action:'Take a pen and draw one funny little creature on paper.',why:'Making something offers a different kind of stimulation.'},connect:{icon:'💬',label:'Connect with someone',action:'Put your phone down and say hello to someone nearby. If you are alone, write one line to someone you care about.',why:'Connection can be more satisfying than another swipe.'},start:{icon:'🌱',label:'Start something small',action:'Open what you have been postponing. Do the very first tiny step — just 30 seconds.',why:'Starting small can make a transition easier.'}};let c=choices[escapeChoice];if(escapeStep===0)return `<section class="escape-flow"><div class="eyebrow">YOUR ESCAPE · 1 OF 3</div><h1>What would feel good <em>after</em> scrolling?</h1><p>Not what you “should” do. Choose something you might genuinely enjoy.</p><div class="escape-choices">${Object.entries(choices).map(([id,a])=>`<button class="escape-choice ${escapeChoice===id?'on':''}" data-escape-choice="${id}"><span>${a.icon}</span>${a.label}</button>`).join('')}</div>${button('Let’s do it →','escapeForward','btn-primary btn-wide')}<button class="escape-skip" data-action="home">Not now</button></section>`;if(escapeStep===1)return `<section class="escape-flow"><div class="eyebrow">YOUR ESCAPE · 2 OF 3</div><h1>Wake up your <em>attention.</em></h1><p>Tap the three stepping stones in order. There is no timer.</p><div class="stone-track">${['Notice','Choose','Go'].map((name,i)=>`<button class="stone ${i<targetCount?'done':''} ${i===targetCount?'current':''}" data-stone="${i}" ${i!==targetCount?'disabled':''}><span>${i<targetCount?'✓':i+1}</span><small>${name}</small></button>`).join('')}</div><div class="escape-message">${['Look away from the screen and notice one thing around you.','Take one easy breath. You can choose what comes next.','Feel your feet on the floor. You are ready to move.','You did it. The next part happens in real life.'][targetCount]}</div>${targetCount>=3?button('Take me to my mission →','escapeForward','btn-primary btn-wide'):''}<button class="escape-skip" data-action="escapeForward">Skip the exercise</button></section>`;return `<section class="escape-flow"><div class="eyebrow">YOUR ESCAPE · 3 OF 3</div><div class="escape-reward">${c.icon}</div><h1>Your next <em>tiny adventure.</em></h1><p class="mission-lead">${c.action}</p><div class="mission-note">${c.why} You don't have to feel motivated first.</div>${button('I’m putting my phone down ↗','escapeLeave','btn-primary btn-wide')}<button class="escape-skip" data-action="escapeDone">I’m not ready yet</button></section>`}
// V18: independent skill games share the same CBT-style check-in and offline follow-through.
const practiceCatalog={
 loop:{name:'Just One More',sprite:'nib',lesson:'loop',quest:'Choose an ending cue before your next planned scroll (for example, after three posts).',thought:'If I stop now, I might miss the best video.'},
 notifications:{name:'Notification Ninja',sprite:'potato',lesson:'fomo',quest:'Mute one nonessential alert for your next focused activity.',thought:'Every notification needs my attention right away.'},
 switch:{name:'Tiny Step Quest',sprite:'dragon',lesson:'switch',quest:'Open the task you have been avoiding, and try its first 30-second step.',thought:'I need to feel motivated before I can start.'},
 thought:{name:'Thought Detective',sprite:'potato',lesson:'fomo',quest:'When a notification feels urgent, ask: what evidence says it must be checked now?',thought:'If I leave, I will miss everything.'},
 focus:{name:'Nib vs. the Noise',sprite:'nib',lesson:'fomo',quest:'Put your phone out of reach for two minutes while working on one chosen task.',thought:'I have to respond to every distraction.'},
 snack:{name:'Infinite Snack Machine',sprite:'potato',lesson:'loop',quest:'Practice choosing an ending cue for your next break, then close the feed at that cue.',thought:'One more reel will finally satisfy me.'},
 blob:{name:'Boredom Blob',sprite:'blob',lesson:'urge',quest:'Notice one brief moment of boredom without automatically opening an app. Move around if that helps.',thought:'Feeling bored means I have to find something on my phone.'},
 dragon:{name:'Procrastination Dragon',sprite:'dragon',lesson:'switch',quest:'Pick one task and do only its first manageable step for 30 seconds.',thought:'This task is too big; I cannot even begin.'},
 reward:{name:'Reward Experiment',sprite:'nib',lesson:'stress',quest:'Try a one-minute phone-free break. Notice whether it met the need you identified.',thought:'Scrolling always gives me the rest I need.'}
};
const chapterStages={thought:-0.5,focus:-0.25,snack:0,blob:1,dragon:2,reward:-1};
let practice=null;
function startPractice(id){
 if(!practiceCatalog[id])return;
 clearRound();stopFocusRunner();stopSnackGame();stopAdventureClock();
 practice={id,step:'assessment',trigger:null,belief:null,urge:null,attempted:null,helpful:null,recordId:null,coachQuestion:'',coachSource:'',coachAnswer:'',coachInsight:'',coachBusy:false,coachError:'',allowHistory:false,reflectionSaved:false};
 view='practice';render();window.scrollTo(0,0);
}

// Optional, brief CBT-informed coaching. Nothing is sent until the user chooses to ask.
// Recent feedback is transmitted only after explicit opt-in per session.
function practiceHistorySummary(){
 if(!practice?.allowHistory)return [];
 return (state.gameHistory||[]).filter(r=>r.completed&&['helpful','nothelpful'].includes(r.helpful))
   .slice(-5).map(r=>({game:String(r.game||'').slice(0,30),helpful:r.helpful,trigger:String(r.trigger||'').slice(0,30)}));
}
function coachLocal(stage){
 const q=practiceCatalog[practice?.id];
 if(stage==='before')return {message:`When you think “${q.thought}”, what is one alternative explanation that could also be true?`,nextStep:q.quest,source:'local'};
 return {message:practice?.helpful==='helpful'?'You noticed something that helped. What made that step workable for you?':'Trying an experiment gives you information, even when it does not help. What could you change next time?',nextStep:q.quest,source:'local'};
}
async function askPracticeCoach(stage){
 if(!practice||practice.coachBusy)return;
 const p=practice, q=practiceCatalog[p.id];
 const answerNode=document.querySelector('#coach-answer');
 if(answerNode)p.coachAnswer=answerNode.value.slice(0,300);
 p.coachBusy=true;p.coachError='';render();
 try{
  const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),9500);
  let resp;
  try {resp=await fetch('/api/behavior-coach',{method:'POST',headers:{'Content-Type':'application/json'},signal:ctrl.signal,body:JSON.stringify({stage,game:p.id,trigger:p.trigger,belief:p.belief,urge:p.urge,thought:q.thought,answer:p.coachAnswer,attempted:p.attempted,helpful:p.helpful,history:practiceHistorySummary()})});}
  finally{clearTimeout(timer)}
  if(!resp.ok)throw new Error('AI unavailable');
  const result=await resp.json();if(typeof result.message!=='string'||typeof result.nextStep!=='string')throw new Error('Invalid coach response');
  if(practice!==p)return;
  if(stage==='before'){p.coachQuestion=result.message.slice(0,320);p.coachSource=result.source||'local';}
  else{p.coachInsight=result.message.slice(0,340);p.coachSource=result.source||'local';p.step='insight';const rec=state.gameHistory.find(x=>x.id===p.recordId);if(rec){rec.coachInsight=p.coachInsight;save();}}
 }catch{
  if(practice!==p)return;
  const local=coachLocal(stage);if(stage==='before')p.coachQuestion=local.message;
  else {p.coachInsight=local.message;p.step='insight';}
  p.coachSource='local';p.coachError='AI unavailable — showing a local reflection.';
 }finally{if(practice===p){p.coachBusy=false;render();}}
}
function persistPracticeReflection(){
 if(!practice||practice.reflectionSaved)return;
 const q=practiceCatalog[practice.id];
 const rec=state.gameHistory.find(x=>x.id===practice.recordId);
 if(rec){Object.assign(rec,{actionAttempted:practice.attempted,helpful:practice.helpful,reflectedAt:new Date().toISOString(),coachQuestion:practice.coachQuestion.slice(0,320),coachAnswer:practice.coachAnswer.slice(0,300)});}
 state.reflections.push({title:q.name+' · CBT check-in',gameId:practice.id,gameRecordId:practice.recordId,choice:JSON.stringify({trigger:practice.trigger,belief:practice.belief,urge:practice.urge,offlineAttempted:practice.attempted,helpful:practice.helpful}),at:new Date().toISOString()});
 state.reflections=state.reflections.slice(-250);if(practice.attempted===true)state.missions++;
 practice.reflectionSaved=true;save();
}

function practiceStartPlay(){
 if(!practice||!practice.trigger||practice.belief===null||practice.urge===null)return;
 practice.step='play';const id=practice.id;
 if(id in chapterStages){beginAdventure();adventure.stage=chapterStages[id];adventure.thought=0;adventure.steps=0;adventure.taps=0;adventure.quiet=0;
  if(id==='focus')focusInit();if(id==='blob')startQuietClock();render();return;}
 game=id;phase=0;stepIndex=0;sessionComplete=false;view='games';render();
}
function practiceEndPlay(){
 if(!practice)return;
 stopFocusRunner();stopSnackGame();stopAdventureClock();clearRound();
 // Save game completion immediately. The offline task and reflection are OPTIONAL.
 if(!practice.recordId){
  const record={id:crypto.randomUUID?.()||String(Date.now()),game:practice.id,at:new Date().toISOString(),completed:true,actionAttempted:null,helpful:null,trigger:practice.trigger,belief:practice.belief,urge:practice.urge,coachQuestion:practice.coachQuestion.slice(0,320),coachAnswer:practice.coachAnswer.slice(0,300)};
  practice.recordId=record.id;
  state.gameHistory.push(record);
  state.gameHistory=state.gameHistory.slice(-150);
  grantXP(10);
  save();
 }
 practice.step='quest';view='practice';render();window.scrollTo(0,0);
}
function practiceFinish(){
 if(!practice)return;
 persistPracticeReflection();
 practice=null;navigate('games');toast('Game and reflection saved on this device.');
}
function practiceSaveAndLeave(){
 if(!practice)return;
 // If the user leaves at the quest, the game is already completed and saved.
 const wasSaved=!!practice.recordId;
 practice=null;navigate('games');
 toast(wasSaved?'Game completion saved. You can try the offline task anytime.':'Returning to games.');
}
